import {bird,doodle} from './art.js';
export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s.toLocaleLowerCase('pt-BR').replace(/^./,c=>c.toUpperCase()).replace(/íria/g,'Íria').replace(/maela/g,'Maela').replace(/oren/g,'Oren').replace(/lior/g,'Lior').replace(/nessa/g,'Nessa');
export const paragraphs=arr=>arr.map(s=>`<p class="${s.startsWith('“')?'dialogue':''}">${esc(s).replace(/\n/g,'<br>')}</p>`).join('');
export const intro=(label,heading,desc)=>`<div class="page-intro"><span class="eyebrow">${label}</span><h1>${heading}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
export function home(d,saved){return `<section class="cover"><div class="cover-top"><span>UM PERSONAGEM DE AURORA</span><span>22 ANOS · ARTESÃO · INVENTOR</span></div><div class="cover-grid"><div class="cover-copy"><div class="edition"><span class="little-star">✳</span> O MUNDO AINDA NÃO ESTÁ PRONTO.</div><h1>A coleção<br>dos <em>talvez</em><span class="ink-period">.</span></h1><p class="cover-summary">Lior Bellamy tem uma ideia.<br>Na verdade, tem várias.<br><span>Esse sempre foi o problema.</span></p><a class="ink-button" href="#/historia/1">Abrir a história <span>↗</span></a>${saved?`<a class="resume" href="#/historia/${saved}">Continuar no capítulo ${String(saved).padStart(2,'0')} →</a>`:''}<p class="cover-note">Doze capítulos sobre criar, errar<br>e aprender a deixar algumas coisas como estão.</p></div><div class="cover-art"><div class="orbit orbit-one" aria-hidden="true"></div><div class="orbit orbit-two" aria-hidden="true"></div><span class="tape tape-top"></span><span class="drawing-label">OFICINA BELLAMY / ESTUDO Nº 001</span>${bird()}<span class="handwriting bird-note">asas: quase prontas.<br>voo: pensando se faço...</span><button class="wind-button" id="wind">↻ <span>Dar corda</span></button><span class="wind-caption" aria-live="polite">Ele ainda não voa. Mas tentou.</span><span class="art-stamp">NÃO<br>DESCARTAR</span></div></div><div class="cover-bottom"><span>MADEIRA, TINTA & ALGUMAS MÁS DECISÕES.</span><a href="#intro">TEM MAIS COISA NA GAVETA ↓</a></div></section><section class="opening" id="intro"><div class="margin-label">ANTES DE ABRIR<br>A PRIMEIRA PÁGINA</div><div><p class="opening-big">Algumas coisas quebradas<br>precisam de conserto.<br><em>Outras, de um pedido de desculpas.</em></p><div class="opening-body"><p>Lior sempre acreditou que o mundo poderia ser mais interessante. Criado entre ferramentas, desenhos e mecanismos mágicos, aprendeu a transformar objetos comuns em ideias improváveis.</p><p>Mas há coisas que não aceitam uma segunda versão tão facilmente: uma promessa quebrada, uma amizade abalada ou a confiança de alguém.</p></div></div><span class="margin-flower">${doodle('flower')}</span></section><section class="shelf"><div class="section-label"><span>ESCOLHA POR ONDE COMEÇAR</span><span>SEM ORDEM OBRIGATÓRIA.</span></div><div class="shelf-links"><a href="#/historia"><span class="shelf-number">01</span><h2>Uma história <br>em doze partes.</h2><p>Da gaveta da infância ao último sonho.</p><span class="shelf-arrow">↗</span></a><a href="#/lior"><span class="shelf-number">02</span><h2>Um rapaz. <br>Muitas versões.</h2><p>O que ele mostra. O que ainda está aprendendo.</p><span class="shelf-arrow">↗</span></a><a href="#/caderno"><span class="shelf-number">03</span><h2>Por favor, <br>mexa na gaveta.</h2><p>Pequenas ideias que não couberam na história.</p><span class="shelf-arrow">↗</span></a></div></section><section class="quote-strip"><span class="handwriting">anotação sem data</span><blockquote>“Se uma coisa pode ser diferente, por que alguém escolheria deixá-la exatamente como está?”</blockquote><span>— LIOR BELLAMY</span></section>`}
export function contents(d){return `<section class="contents-page">${intro('01 / A HISTÓRIA','Uma coisa puxa<br><em>a outra.</em>','Doze capítulos. Uma história inteira. Comece pela primeira gaveta ou encontre a página que procura.')}<div class="contents-layout"><aside class="contents-note">${doodle('bird')}<p class="handwriting">Era só um pássaro<br>que não voava.</p><p>O resto veio depois.</p><a class="ink-button" href="#/historia/1">Começar a leitura ↗</a><a class="text-link" href="#/historia/tudo">Ler tudo em sequência →</a><span class="small-print">Texto integral · ${Math.ceil(d.chapters.flatMap(c=>c.paragraphs).join(' ').split(/\s+/).length/200)} min de leitura</span></aside><ol class="chapter-list">${d.chapters.map((c,i)=>`<li><a href="#/historia/${i+1}"><span>${String(i+1).padStart(2,'0')}</span><div><h2>${title(c.title)}</h2><p>${esc(c.paragraphs[0])}</p></div><b>↗</b></a></li>`).join('')}</ol></div></section>`}
export function reader(d,key,extra=false){const all=key==='tudo',items=extra?d.scenes:d.chapters,n=all?0:Math.min(items.length-1,Math.max(0,(Number(key)||1)-1)),selected=all?items:[items[n]],base=extra?'extras':'historia';return `<div class="reader-shell"><aside class="reader-index"><a class="back-small" href="#/${base}">← ${extra?'Cenas extras':'Todos os capítulos'}</a><p class="eyebrow">${extra?'À MARGEM DA HISTÓRIA':'A COLEÇÃO DOS TALVEZ'}</p><ol>${items.map((c,i)=>`<li><a href="#/${base}/${i+1}" ${!all&&i===n?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${title(c.title)}</a></li>`).join('')}</ol>${!extra?'<a class="text-link" href="#/historia/tudo">Ler em sequência ↗</a>':''}</aside><div class="reader-paper"><div class="reader-toolbar"><span>${extra?'CENA EXTRA':all?'LEITURA COMPLETA':`CAPÍTULO ${String(n+1).padStart(2,'0')} / 12`}</span><div><button id="font-down" aria-label="Diminuir texto">A−</button><button id="font-up" aria-label="Aumentar texto">A+</button><button id="reader-theme" aria-label="Alternar leitura noturna">◐</button><button id="focus-reading" aria-label="Alternar leitura sem distrações" aria-pressed="false">Foco</button><button id="copy-text" aria-label="Copiar texto da leitura">Copiar</button></div></div><div class="reader-prose">${extra?'<p class="extra-disclaimer">Cena complementar. Acontece antes do sonho final.</p>':''}${selected.map((c,i)=>`<article id="chapter-${all?i+1:n+1}"><span class="chapter-pretitle">${extra?'CENA':'CAPÍTULO'} ${String(all?i+1:n+1).padStart(2,'0')}</span><h1>${title(c.title)}</h1><div class="chapter-flourish">✳</div>${paragraphs(c.paragraphs)}<div class="end-flourish">· &nbsp; · &nbsp; ·</div></article>`).join('')}</div><nav class="reader-pagination" aria-label="Navegação da leitura">${!all&&n>0?`<a href="#/${base}/${n}"><small>ANTERIOR</small>${title(items[n-1].title)}<span>←</span></a>`:'<span></span>'}${!all&&n<items.length-1?`<a href="#/${base}/${n+2}"><small>PRÓXIMA PÁGINA</small>${title(items[n+1].title)}<span>→</span></a>`:`<a href="#/${extra?'caderno':'lior'}"><small>A HISTÓRIA TERMINA AQUI.</small>${extra?'Voltar ao caderno':'Conhecer Lior por outro lado'}<span>↗</span></a>`}</nav></div></div>`}
export function profile(d){const p=d.profile;const behaviors=p['COMO ELE SE COMPORTA'].split(/\n\s*\n/).map(s=>s.split(':\n'));return `<section class="profile-page">${intro('02 / QUEM É LIOR','Uma boa intenção.<br><em>Alguns parafusos a menos.</em>','Criativo, sociável e perfeitamente capaz de transformar uma tarefa simples em uma tarde complicada.')}<div class="profile-opener"><div class="identity-sheet"><span class="tape"></span><p class="eyebrow">FICHA DE OFICINA</p><h2>Lior<br><em>Bellamy</em></h2><dl><div><dt>IDADE</dt><dd>22 anos</dd></div><div><dt>OFÍCIO</dt><dd>Artesão & inventor</dd></div><div><dt>MATERIAIS</dt><dd>Madeira, tinta, tecido,<br>mecanismos simples.</dd></div></dl><span class="signature handwriting">L. Bellamy</span><span class="identity-doodle">${doodle('lamp')}</span></div><div class="profile-description">${paragraphs(p.PERSONALIDADE.split(/\n\s*\n/))}</div></div><div class="traits"><div><span class="eyebrow">O QUE FAZ FUNCIONAR</span><h2>As boas peças.</h2>${p.QUALIDADES.split('\n').map(s=>`<p><b>${esc(s.split(':')[0])}</b>${esc(s.slice(s.indexOf(':')+1))}</p>`).join('')}</div><div><span class="eyebrow">O QUE AINDA PRECISA DE AJUSTE</span><h2>As arestas.</h2>${p.DEFEITOS.split('\n').map(s=>`<p><b>${esc(s.split(':')[0])}</b>${esc(s.slice(s.indexOf(':')+1))}</p>`).join('')}</div></div><section class="behavior-section"><h2>Depende de quem pergunta.</h2><div class="behavior-list">${behaviors.map((s,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span>${esc(s[0])}<b>+</b></summary><p>${esc(s.slice(1).join(':\n'))}</p></details>`).join('')}</div></section><div class="wishes"><section><span class="eyebrow">O QUE PROCURA</span><h2>Um lugar para suas ideias.</h2>${paragraphs(p.OBJETIVOS.split('\n'))}</section><section><span class="eyebrow">O QUE TEME</span><h2>Perder quem fica por perto.</h2>${paragraphs(p.MEDOS.split('\n'))}</section></div></section>`}
const noteNames=['Uma janela de saudade','Tentativa nº…','Uma luz para escutar','O problema de escolher','Não modificar','A música de Nessa','Antes de mudar a casa','Pequeno. E terminado.'];const noteIcons=['moon','bird','lamp','flower','flower','box','letter','bird'];
export function notebook(d){return `<section class="notebook-page">${intro('03 / O CADERNO DOS TALVEZ','Não é bagunça.<br><em>São possibilidades.</em>','Anotações de Lior. Projetos por acabar. Coisas pequenas demais para jogar fora. Abra um papel.')}<div class="desk-label"><span>CONTEÚDO DA GAVETA</span><span class="handwriting">pode mexer. só devolve depois.</span></div><div class="note-grid">${d.notes.map((s,i)=>`<button class="note-card note-${i%4}" data-note="${i}" aria-label="Abrir anotação: ${noteNames[i]}"><span class="note-pin"></span><small>FOLHA ${String(i+1).padStart(2,'0')}</small>${doodle(noteIcons[i])}<h2>${noteNames[i]}</h2><span class="note-open">desdobrar ↗</span></button>`).join('')}</div><section class="curiosities"><div><span class="eyebrow">VINTE COISAS QUE TALVEZ VOCÊ NÃO SAIBA</span><h2>Nas margens<br>é que ele aparece.</h2><p>Hábitos, pequenas contradições e a vida que existe entre um projeto e outro.</p></div><div class="curiosity-picker"><div class="curiosity-counter"><span id="curiosity-counter">01 / 20</span><div><button id="cur-prev" aria-label="Curiosidade anterior">←</button><button id="cur-next" aria-label="Próxima curiosidade">→</button></div></div><p id="curiosity-text" aria-live="polite">${esc(d.curiosities[0])}</p><details><summary>Ver todas as curiosidades</summary><ol>${d.curiosities.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details></div></section></section>`}
export function extras(d){return `<section class="extras-page">${intro('04 / ENTRELINHAS','O que não coube<br><em>na história.</em>','Cinco cenas complementares. Todas acontecem antes do sonho final e podem ser lidas separadamente.')}<div class="extra-stack">${d.scenes.map((s,i)=>`<a href="#/extras/${i+1}" class="extra-row"><span class="extra-icon">${doodle(['moon','box','flower','lamp','letter'][i])}</span><span class="extra-meta">CENA 0${i+1}<h2>${title(s.title)}</h2><p>${esc(i===4?'Uma carta para Íria. Guardada, nunca entregue.':s.paragraphs[0])}</p></span><span class="extra-arrow">↗</span></a>`).join('')}</div></section>`}
export function credits(){return `<section class="credits-page">${intro('REFERÊNCIAS & CRÉDITOS','Ideias também<br><em>têm companhia.</em>','Três influências criativas. Um personagem com suas próprias escolhas, limites e consequências.')}<div class="influences"><article><span class="paint-swatch blue">01</span><small>BLEACH</small><h2>Gremmy<br>Thoumeaux</h2><p>A confiança quase excessiva no poder das ideias. A imaginação e a dificuldade de lidar com limites.</p></article><article><span class="paint-swatch orange">02</span><small>JUJUTSU KAISEN</small><h2>Mahito</h2><p>A irreverência, a provocação e a curiosidade irresponsável. Uma influência de postura, sem servir de modelo moral ou reproduzir sua crueldade.</p></article><article><span class="paint-swatch green">03</span><small>BLACK CLOVER</small><h2>Rill<br>Boismortier</h2><p>A paixão artística, a energia e o entusiasmo de quem se entrega por inteiro à própria criação.</p></article></div><div class="credit-note"><p>Essas referências descrevem influências, não equivalências. Lior tem limitações e conflitos próprios, inseridos na ambientação de Aurora.</p><span class="handwriting">nenhuma ideia nasce completamente sozinha.</span></div><div class="colophon"><span class="eyebrow">ESTE CADERNO PERTENCE A</span><h2>ezy.xyz</h2><p>Personagem e direção criativa.</p><p class="small-print">Desenvolvimento do site com auxílio de IA.</p><span>LIOR BELLAMY · A COLEÇÃO DOS TALVEZ</span></div></section>`}
